import { MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createText } from '@/text';
import * as primitives from '@/primitives';

export default function createNode(config, ctx) {
  const { Group, DirectionalLight, Color } = ctx.THREE;

  // Root object for this node
  const root = new Group();

  // Store disposables
  const _cleanups = [];
  const _timelines = [];

  // Load GLB mesh
  let _gltf = null;
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      _gltf = gltf;
      root.add(gltf.scene);
    });
  }

  // Apply cinematic primitives
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (ctx.primitives && typeof ctx.primitives[prim.name] === 'function') {
        const instance = ctx.primitives[prim.name](root, prim.params);
        if (instance) {
          if (instance.cleanup) _cleanups.push(instance.cleanup);
          if (instance.timeline) _timelines.push(instance.timeline);
        }
      }
    }
  }

  // Accent rim light (signal red)
  const rimLight = new DirectionalLight(new Color('#ff2a38'), 0.6);
  rimLight.position.set(0, 0, 5);
  root.add(rimLight);
  _cleanups.push(() => rimLight.dispose && rimLight.dispose());

  // Interaction handlers
  const _handlers = {};

  // Hover rise‑in effect (0.15 scene units)
  _handlers.hover = () => {
    const tl = gsap.to(root.position, {
      y: root.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    _timelines.push(tl);
  };

  // Click emit event
  _handlers.click = () => {
    ctx.emit('hub-collection.select', {});
  };

  // Attach handlers to userData
  root.userData.handlers = _handlers;

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose GLTF resources
    if (_gltf && _gltf.scene) {
      _gltf.scene.traverse((obj) => {
        if (obj.isMesh) {
          if (obj.geometry) obj.geometry.dispose();
          if (obj.material) {
            if (Array.isArray(obj.material)) {
              obj.material.forEach((m) => m.dispose && m.dispose());
            } else {
              obj.material.dispose && obj.material.dispose();
            }
          }
        }
      });
    }

    // Run primitive cleanups
    _cleanups.forEach((fn) => {
      try {
        fn();
      } catch (e) {
        // ignore cleanup errors
      }
    });

    // Kill GSAP timelines
    _timelines.forEach((tl) => {
      try {
        tl.kill();
      } catch (e) {
        // ignore
      }
    });
  };

  // If there were any text items (none in this spec) they would be added here
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize,
      color: item.role === 'label' ? '#e8ecf2' : '#16161d',
      align: 'center',
    });
    root.add(txt);
  }

  return root;
}
